import{_ as a,c as n,a as t,o as p}from"./app-BHSdKjYv.js";const e="/aosai-blog/DeepLearning/Activation/04_silu.png",m={};function l(i,s){return p(),n("div",null,[...s[0]||(s[0]=[t('<h2 id="_1-数学原理-x-乘以-sigmoid" tabindex="-1"><a class="header-anchor" href="#_1-数学原理-x-乘以-sigmoid"><span>1. 数学原理：x 乘以 Sigmoid</span></a></h2><p>2017 年，Google Brain 的 researchers 在寻找比 ReLU 更好的激活函数时，发现了一个简单的公式：<strong>x 乘以 Sigmoid(x)</strong>。他们给它取名 <strong>Swish</strong>，来自 &quot;self-gated activation&quot;（自门控激活）。</p><p>后来 PyTorch 把它收录进自己的库，改名叫 <strong>SiLU</strong>（Sigmoid Linear Unit）。名字不同，但本质一样：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>SiLU</mtext><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mi>x</mi><mo>⋅</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mfrac><mi>x</mi><mrow><mn>1</mn><mo>+</mo><msup><mi>e</mi><mrow><mo>−</mo><mi>x</mi></mrow></msup></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\text{SiLU}(x) = x \\cdot \\sigma(x) = \\frac{x}{1+e^{-x}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">SiLU</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8769em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.1076em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6973em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight">x</span></span></span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><figure><img src="'+e+`" alt="1. SiLU 激活函数图像" width="560" tabindex="0" loading="lazy"><figcaption>1. SiLU 激活函数图像</figcaption></figure><p><strong>和 ReLU 的区别：</strong></p><table><thead><tr><th>特性</th><th>ReLU</th><th>SiLU</th></tr></thead><tbody><tr><td>公式</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>max</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0</mn><mo separator="true">,</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\max(0, x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">max</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>⋅</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">x \\cdot \\sigma(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></td></tr><tr><td>负半轴</td><td>直接为 0</td><td>有微小负值（约 -0.28）</td></tr><tr><td>平滑性</td><td>不平滑（x=0 处折角）</td><td>平滑（处处可导）</td></tr></tbody></table><p>SiLU 在负半轴不是直接为 0，而是有一个微小的负值。这使得 SiLU 比 ReLU 更平滑，理论上表达能力更强。</p><blockquote><p><strong>一句话记住</strong>：SiLU = Swish = <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>⋅</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">x \\cdot \\sigma(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>，PyTorch 用 <code>nn.SiLU()</code>。</p></blockquote><h2 id="_2-梯度" tabindex="-1"><a class="header-anchor" href="#_2-梯度"><span>2. 梯度</span></a></h2><p>SiLU 的导数可以用自身表示：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msup><mtext>SiLU</mtext><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>⋅</mo><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>x</mi><mo>⋅</mo><mo stretchy="false">(</mo><mn>1</mn><mo>−</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo stretchy="false">)</mo><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\text{SiLU}&#39;(x) = \\sigma(x) \\cdot (1 + x \\cdot (1 - \\sigma(x))) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0751em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord text"><span class="mord">SiLU</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8251em;"><span style="top:-3.1362em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)))</span></span></span></span></span></p><p>这个导数在 x=0 附近有负值，这意味着 SiLU 有&quot;自正则化&quot;效果——部分神经元的梯度为负，会轻微抑制激活值。</p><h2 id="_3-pytorch-中的使用" tabindex="-1"><a class="header-anchor" href="#_3-pytorch-中的使用"><span>3. PyTorch 中的使用</span></a></h2><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token comment"># SiLU 激活函数</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>nn <span class="token keyword">as</span> nn</span>
<span class="line">silu <span class="token operator">=</span> nn<span class="token punctuation">.</span>SiLU<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者用函数式接口</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>functional <span class="token keyword">as</span> F</span>
<span class="line">output <span class="token operator">=</span> F<span class="token punctuation">.</span>silu<span class="token punctuation">(</span><span class="token builtin">input</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-应用场景-什么时候用-silu" tabindex="-1"><a class="header-anchor" href="#_4-应用场景-什么时候用-silu"><span>4. 应用场景：什么时候用 SiLU？</span></a></h2><p>激活函数是工具，不同的场景用不同的工具。</p><p><strong>服务器端追求精度时用 SiLU：</strong></p><table><thead><tr><th>场景</th><th>为什么用 SiLU</th><th>例子</th></tr></thead><tbody><tr><td>Kaggle 比赛</td><td>SiLU 比 ReLU 精度高 1-2%</td><td>争取 Top 排名</td></tr><tr><td>论文复现</td><td>很多论文用 SiLU</td><td>保证实验可复现</td></tr><tr><td>深层网络</td><td>SiLU 更平滑，梯度流动更好</td><td>ResNet-101、EfficientNet</td></tr></tbody></table><p><strong>实际案例：</strong></p><ul><li>EfficientNet-B7：用 SiLU，ImageNet Top-1 准确率 84.3%</li><li>ConvNeXt：用 SiLU，精度比 ReLU 高约 1.5%</li></ul><blockquote><p><strong>一句话记住</strong>：服务器端追求精度用 SiLU。</p></blockquote>`,22)])])}const o=a(m,[["render",l]]),r=JSON.parse('{"path":"/blogs/DeepLearning/ActivationFunction/04_SiLU.html","title":"SiLU 激活函数","lang":"en-US","frontmatter":{"title":"SiLU 激活函数","date":"2026/05/30","categories":["激活函数"],"tags":["激活函数","SiLU","Swish"]},"headers":[{"level":2,"title":"1. 数学原理：x 乘以 Sigmoid","slug":"_1-数学原理-x-乘以-sigmoid","link":"#_1-数学原理-x-乘以-sigmoid","children":[]},{"level":2,"title":"2. 梯度","slug":"_2-梯度","link":"#_2-梯度","children":[]},{"level":2,"title":"3. PyTorch 中的使用","slug":"_3-pytorch-中的使用","link":"#_3-pytorch-中的使用","children":[]},{"level":2,"title":"4. 应用场景：什么时候用 SiLU？","slug":"_4-应用场景-什么时候用-silu","link":"#_4-应用场景-什么时候用-silu","children":[]}],"git":{"createdTime":1780239520000,"updatedTime":1780239520000,"contributors":[{"name":"jinkai","email":"1213860588@qq.com","commits":1}]},"filePathRelative":"blogs/DeepLearning/ActivationFunction/04_SiLU.md"}');export{o as comp,r as data};
